effect.shader:
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

void main() {
    vec2 t = acTexelSize * thickness;
    float tl = dot(texture(inputImg, acScreenNorm + vec2(-t.x,-t.y)).rgb, LUMA);
    float tc = dot(texture(inputImg, acScreenNorm + vec2( 0.0,-t.y)).rgb, LUMA);
    float tr = dot(texture(inputImg, acScreenNorm + vec2( t.x,-t.y)).rgb, LUMA);
    float ml = dot(texture(inputImg, acScreenNorm + vec2(-t.x, 0.0)).rgb, LUMA);
    float mr = dot(texture(inputImg, acScreenNorm + vec2( t.x, 0.0)).rgb, LUMA);
    float bl = dot(texture(inputImg, acScreenNorm + vec2(-t.x, t.y)).rgb, LUMA);
    float bc = dot(texture(inputImg, acScreenNorm + vec2( 0.0, t.y)).rgb, LUMA);
    float br = dot(texture(inputImg, acScreenNorm + vec2( t.x, t.y)).rgb, LUMA);

    float gx = -tl - 2.0*ml - bl + tr + 2.0*mr + br;
    float gy = -tl - 2.0*tc - tr + bl + 2.0*bc + br;
    float g = clamp(sqrt(gx*gx + gy*gy) * sens, 0.0, 1.0);

    vec4 orig = texture(inputImg, acScreenNorm);
    vec3 fundo = mix(orig.rgb, vec3(1.0), fill);
    fragColor = vec4(mix(fundo, lineColor.rgb, g * lineColor.a), orig.a);
}
